using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Htt.Host.Api;
using Htt.Host.Api.MasterData;
using Htt.Infrastructure.Documents;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class CardOcrTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private static readonly byte[] Png=[137,80,78,71,13,10,26,10,0];
 private static async Task<HttpResponseMessage> Queue(HttpClient c,Guid customer,string? key=null){using var request=new HttpRequestMessage(HttpMethod.Post,$"/api/v1/crm/cards/{customer}");var form=new MultipartFormDataContent();var bytes=new ByteArrayContent(Png);bytes.Headers.ContentType=new("image/png");form.Add(bytes,"file","selected.png");request.Content=form;request.Headers.Add("Idempotency-Key",key??Code());return await c.SendAsync(request);}
 private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();
 private sealed class Scanner(bool clean=true):IFileScanner{public int Calls;public Task<bool> IsCleanAsync(byte[] b,CancellationToken ct){Calls++;return Task.FromResult(clean);}}
 private sealed class Ocr(string? error=null):ICardRecognizer{public int Calls;public Task<JsonElement> RecognizeAsync(Guid id,byte[] b,string type,CancellationToken ct){Calls++;if(error is not null)throw new DocumentWorkException(error,WorkFailure.Retry);return Task.FromResult(JsonSerializer.SerializeToElement(new{name="Card person",email="card@example.test",phone="0412345678",branchIds=Array.Empty<Guid>()}));}}
 private async Task<Guid> Customer(HttpClient c)=>await Create(c,"/customers",new CustomerDraft(Code(),"Card customer",null));
 private async Task PrepareWorker()=>await S("DELETE FROM crm.card_jobs WHERE company_id<>@c",("c",db.Company));
 [Fact]public async Task Scanned_card_result_is_private_suggestion_until_manual_confirmation_then_office_review()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var customer=await Customer(c);var key=Code();var job=await Expect(await Queue(c,customer,key),HttpStatusCode.Accepted);var id=Id(job);Assert.Equal(id,Id(await Expect(await Queue(c,customer,key),HttpStatusCode.Accepted)));await PrepareWorker();await using var source=NpgsqlDataSource.Create(db.Worker);var scanner=new Scanner();var ocr=new Ocr();Assert.True(await new CardOcrWorker(source,scanner,ocr).ProcessOneAsync());Assert.Equal(1,scanner.Calls);Assert.Equal(1,ocr.Calls);var result=await Get(c,$"/crm/cards/jobs/{id}");Assert.Equal("SUCCEEDED",result.GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM crm.mobile_drafts WHERE company_id=@c",("c",db.Company)));var data=new CrmDraftData("Confirmed person",Email:"confirmed@example.test");var confirmKey=Code();var draft=await Expect(await Send(c,HttpMethod.Post,$"/crm/cards/jobs/{id}/confirm",data,key:confirmKey),HttpStatusCode.Created);Assert.Equal("DRAFT",draft.GetProperty("state").GetString());Assert.Equal("Confirmed person",draft.GetProperty("data").GetProperty("name").GetString());Assert.Equal(Id(draft),Id(await Expect(await Send(c,HttpMethod.Post,$"/crm/cards/jobs/{id}/confirm",data,key:confirmKey),HttpStatusCode.Created)));await Expect(await Send(c,HttpMethod.Post,$"/crm/cards/jobs/{id}/confirm",data),HttpStatusCode.Conflict);Assert.Equal(0L,await S("SELECT count(*)FROM crm.contacts WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Rejected_scan_never_calls_OCR_and_cannot_be_confirmed_or_retried()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=Id(await Expect(await Queue(c,await Customer(c)),HttpStatusCode.Accepted));await PrepareWorker();await using var source=NpgsqlDataSource.Create(db.Worker);var ocr=new Ocr();await new CardOcrWorker(source,new Scanner(false),ocr).ProcessOneAsync();Assert.Equal(0,ocr.Calls);Assert.Equal("REJECTED",(await Get(c,$"/crm/cards/jobs/{id}")).GetProperty("state").GetString());await Expect(await Send(c,HttpMethod.Post,$"/crm/cards/jobs/{id}/retry"),HttpStatusCode.Conflict);await Expect(await Send(c,HttpMethod.Post,$"/crm/cards/jobs/{id}/confirm",new CrmDraftData("Blocked")),HttpStatusCode.Conflict);}
 [Fact]public async Task Transient_OCR_failure_retries_once_without_creating_duplicates()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=Id(await Expect(await Queue(c,await Customer(c)),HttpStatusCode.Accepted));await PrepareWorker();await using var source=NpgsqlDataSource.Create(db.Worker);await new CardOcrWorker(source,new Scanner(),new Ocr("temporary")).ProcessOneAsync();Assert.Equal("RETRY",(await Get(c,$"/crm/cards/jobs/{id}")).GetProperty("state").GetString());await S("UPDATE crm.card_jobs SET available_at=now()WHERE id=@id",("id",id));await new CardOcrWorker(source,new Scanner(),new Ocr()).ProcessOneAsync();var result=await Get(c,$"/crm/cards/jobs/{id}");Assert.Equal("SUCCEEDED",result.GetProperty("state").GetString());Assert.Equal(2,result.GetProperty("attempts").GetInt32());Assert.Equal(0L,await S("SELECT count(*)FROM crm.contacts WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Revocation_before_execution_prevents_external_OCR_and_discards_output()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=Id(await Expect(await Queue(c,await Customer(c)),HttpStatusCode.Accepted));await PrepareWorker();await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='crm.contacts.import'",("c",db.Company));await using var source=NpgsqlDataSource.Create(db.Worker);var ocr=new Ocr();await new CardOcrWorker(source,new Scanner(),ocr).ProcessOneAsync();Assert.Equal(0,ocr.Calls);Assert.Equal("FAILED",await S("SELECT state FROM crm.card_jobs WHERE id=@id",("id",id)));Assert.Equal(DBNull.Value,await S("SELECT suggestion FROM crm.card_jobs WHERE id=@id",("id",id)));}
 [Fact]public async Task Concurrent_claims_and_expired_lease_recovery_reject_stale_completion()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=Id(await Expect(await Queue(c,await Customer(c)),HttpStatusCode.Accepted));await PrepareWorker();async Task<(Guid,Guid)?> Claim(){await using var con=new NpgsqlConnection(db.Worker);await con.OpenAsync();await using var cmd=new NpgsqlCommand("SELECT job_id,lease FROM crm.claim_card()",con);await using var rd=await cmd.ExecuteReaderAsync();return await rd.ReadAsync()?(rd.GetGuid(0),rd.GetGuid(1)):null;}var all=await Task.WhenAll(Claim(),Claim());Assert.Single(all,x=>x is not null);var old=all.Single(x=>x is not null)!.Value;await S("UPDATE crm.card_jobs SET lease_until=now()-interval '1 second'WHERE id=@id",("id",id));var next=(await Claim())!.Value;Assert.NotEqual(old.Item2,next.Item2);await using var con=new NpgsqlConnection(db.Worker);await con.OpenAsync();await using var done=new NpgsqlCommand("SELECT crm.finish_card(@id,@lease,'FAILED','stale',NULL)",con);done.Parameters.AddWithValue("id",id);done.Parameters.AddWithValue("lease",old.Item2);Assert.Equal("HR409",(await Assert.ThrowsAsync<PostgresException>(()=>done.ExecuteNonQueryAsync())).SqlState);}
 [Fact]public async Task Job_and_image_are_not_exposed_to_another_actor_or_company()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=Id(await Expect(await Queue(c,await Customer(c)),HttpStatusCode.Accepted));var staff=await Staff(db,"SALES");using var other=api.Authenticated(staff.Subject);await Expect(await Send(other,HttpMethod.Get,$"/crm/cards/jobs/{id}"),HttpStatusCode.Forbidden);using var otherCompany=api.Authenticated(company:db.OtherCompany);await Expect(await Send(otherCompany,HttpMethod.Get,$"/crm/cards/jobs/{id}"),HttpStatusCode.NotFound);await using var s=await db.SessionAsync();await using var cmd=new NpgsqlCommand("SELECT content FROM crm.card_jobs",s.Connection,s.Transaction);Assert.Equal("42501",(await Assert.ThrowsAsync<PostgresException>(()=>cmd.ExecuteScalarAsync())).SqlState);}
 private sealed class Handler(HttpStatusCode status,string json):HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;Assert.Equal("https://ocr.example.test/selected-card",request.RequestUri!.ToString());return Task.FromResult(new HttpResponseMessage(status){Content=new StringContent(json)});}}
 [Theory][InlineData(429,"card_ocr_transient",true)][InlineData(503,"card_ocr_transient",true)][InlineData(302,"card_ocr_rejected",false)][InlineData(400,"card_ocr_rejected",false)][InlineData(200,"card_ocr_invalid_output",false)]
 public async Task Gateway_status_and_invalid_output_are_classified_without_following_provider_links(int status,string code,bool retry)
 {var h=new Handler((HttpStatusCode)status,"{}");var r=new GatewayCardRecognizer(new(){Endpoint="https://ocr.example.test/selected-card",ApiKey="test-only"},new HttpClient(h));var error=await Assert.ThrowsAsync<DocumentWorkException>(()=>r.RecognizeAsync(Guid.NewGuid(),Png,"image/png",default));Assert.Equal(code,error.Code);Assert.Equal(retry?WorkFailure.Retry:WorkFailure.Permanent,error.Failure);Assert.Equal(1,h.Calls);}
 [Fact]public async Task Configured_gateway_returns_bounded_suggestions_without_customer_or_financial_commands()
 {var h=new Handler(HttpStatusCode.OK,"{\"name\":\"Recognized\",\"email\":\"person@example.test\",\"creditLimit\":9999,\"url\":\"https://evil.invalid\"}");var r=new GatewayCardRecognizer(new(){Endpoint="https://ocr.example.test/selected-card",ApiKey="test-only"},new HttpClient(h));var result=await r.RecognizeAsync(Guid.NewGuid(),Png,"image/png",default);Assert.Equal("Recognized",result.GetProperty("name").GetString());Assert.False(result.TryGetProperty("creditLimit",out _));Assert.False(result.TryGetProperty("url",out _));}

 private sealed class CallbackOcr(Func<Task> callback):ICardRecognizer{public async Task<JsonElement> RecognizeAsync(Guid id,byte[] b,string type,CancellationToken ct){await callback();return JsonSerializer.SerializeToElement(new{name="Do not retain",branchIds=Array.Empty<Guid>()});}}
 [Fact]public async Task Revocation_during_provider_call_discards_suggestion_before_completion()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=Id(await Expect(await Queue(c,await Customer(c)),HttpStatusCode.Accepted));await PrepareWorker();await using var source=NpgsqlDataSource.Create(db.Worker);var recognizer=new CallbackOcr(async()=>{await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='crm.contacts.import'",("c",db.Company));});await new CardOcrWorker(source,new Scanner(),recognizer).ProcessOneAsync();Assert.Equal("FAILED",await S("SELECT state FROM crm.card_jobs WHERE id=@id",("id",id)));Assert.Equal(DBNull.Value,await S("SELECT suggestion FROM crm.card_jobs WHERE id=@id",("id",id)));}
 [Fact]public async Task Five_transient_attempts_stop_and_manual_retry_can_recover_after_configuration_fix()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var id=Id(await Expect(await Queue(c,await Customer(c)),HttpStatusCode.Accepted));await PrepareWorker();await using var source=NpgsqlDataSource.Create(db.Worker);for(var n=0;n<5;n++){await S("UPDATE crm.card_jobs SET available_at=now()WHERE id=@id",("id",id));await new CardOcrWorker(source,new Scanner(),new Ocr("temporary")).ProcessOneAsync();}Assert.Equal("FAILED",(await Get(c,$"/crm/cards/jobs/{id}")).GetProperty("state").GetString());await Expect(await Send(c,HttpMethod.Post,$"/crm/cards/jobs/{id}/retry"),HttpStatusCode.OK);await new CardOcrWorker(source,new Scanner(),new Ocr()).ProcessOneAsync();Assert.Equal("SUCCEEDED",(await Get(c,$"/crm/cards/jobs/{id}")).GetProperty("state").GetString());}
 [Theory][InlineData(false)][InlineData(true)]public async Task Late_audit_failure_rolls_back_card_queue_or_confirmation_and_same_key_recovers(bool confirm)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var customer=await Customer(c);Guid id=Guid.Empty;if(confirm){id=Id(await Expect(await Queue(c,customer),HttpStatusCode.Accepted));await PrepareWorker();await using var source=NpgsqlDataSource.Create(db.Worker);await new CardOcrWorker(source,new Scanner(),new Ocr()).ProcessOneAsync();}var key=Code();Task<HttpResponseMessage> Run()=>confirm?Send(c,HttpMethod.Post,$"/crm/cards/jobs/{id}/confirm",new CrmDraftData("Confirmed"),key:key):Queue(c,customer,key);var action=confirm?"card_confirm":"card_queue";await S($"CREATE FUNCTION crm.test_card_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='crm.{action}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_card_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION crm.test_card_fail()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM crm.mobile_drafts WHERE company_id=@c",("c",db.Company)));if(!confirm)Assert.Equal(0L,await S("SELECT count(*)FROM crm.card_jobs WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_card_fail ON platform.audit_events;DROP FUNCTION crm.test_card_fail()");}await Expect(await Run(),confirm?HttpStatusCode.Created:HttpStatusCode.Accepted);}
 [Fact]public async Task Unconfigured_gateway_fails_explicitly_without_network_use()
 {var handler=new Handler(HttpStatusCode.OK,"{}");var r=new GatewayCardRecognizer(new(),new HttpClient(handler));Assert.Equal("card_ocr_unconfigured",(await Assert.ThrowsAsync<DocumentWorkException>(()=>r.RecognizeAsync(Guid.NewGuid(),Png,"image/png",default))).Code);Assert.Equal(0,handler.Calls);}
}
